[
  {
    "statement": "Several actions can be taken to mitigate road impacts on amphibian populations.",
    "citations": []
  },
  {
    "statement": "Installing culverts or tunnels as road crossings is a widely used method to protect amphibians.",
    "citations": []
  },
  {
    "statement": "Studies have shown that culverts or tunnels were used by 15-85% of amphibians or by 3-15 species.",
    "citations": []
  },
  {
    "statement": "The effectiveness of culverts and tunnels for amphibian crossings varies by design features such as diameter, length, lighting, and substrate.",
    "citations": []
  },
  {
    "statement": "Closing roads during seasonal amphibian migrations protects large numbers of amphibians from death during breeding migrations.",
    "citations": []
  },
  {
    "statement": "Human-assisted crossings involve volunteers moving amphibians across roads.",
    "citations": []
  },
  {
    "statement": "Volunteer patrols in Germany, the UK, and Italy move thousands to half a million toads across roads annually.",
    "citations": []
  },
  {
    "statement": "Despite human-assisted crossing efforts, 64-70% of some amphibian populations still declined over 6-10 years.",
    "citations": []
  },
  {
    "statement": "Warning signage for motorists has been implemented to protect amphibians.",
    "citations": []
  },
  {
    "statement": "Warning signage for motorists is ineffective when used alone.",
    "citations": []
  },
  {
    "statement": "Over 500 toads were still killed on some roads despite the presence of warning signs.",
    "citations": []
  },
  {
    "statement": "Modifying infrastructure, such as moving gully pots 10 cm away from kerbs, decreased great crested newt falls by 80%.",
    "citations": []
  }
]

[
  {
    "statement": "A meta-analysis of 24 studies in North America found that partial harvest methods resulted in smaller reductions in salamander populations than clearcutting.",
    "citations": [
      "24"
    ]
  },
  {
    "statement": "Partial harvest methods include shelterwood harvesting, harvesting trees in small groups, and thinning.",
    "citations": []
  },
  {
    "statement": "Shelterwood harvesting showed mixed results, with some studies finding higher salamander abundance compared to clearcutting.",
    "citations": []
  },
  {
    "statement": "Other studies found that salamander abundance after shelterwood harvesting was similar to, or initially higher before becoming similar to, abundance after clearcutting.",
    "citations": []
  },
  {
    "statement": "Thinning demonstrated better outcomes for salamander populations than clearcutting.",
    "citations": []
  },
  {
    "statement": "Two studies found higher amphibian abundance or a less negative overall response in thinned forests compared to clearcut areas.",
    "citations": [
      "2"
    ]
  },
  {
    "statement": "Harvesting trees in small groups did not result in higher salamander abundance compared to clearcutting when examined individually.",
    "citations": []
  },
  {
    "statement": "All harvesting methods, including partial harvesting, generally decreased salamander abundance compared to unharvested forests.",
    "citations": []
  },
  {
    "statement": "The meta-analysis indicates that partial harvesting methods have less severe impacts on salamander populations than clearcutting.",
    "citations": []
  }
]

[
  {
    "statement": "Fish control methods have shown mixed results for amphibian protection, with both benefits and harms documented.",
    "citations": []
  },
  {
    "statement": "Benefits of fish control include increased amphibian abundance, recruitment, survival and population growth.",
    "citations": []
  },
  {
    "statement": "Removing fish by catching significantly increased the abundance of salamanders or frogs.",
    "citations": []
  },
  {
    "statement": "Removing fish by catching improved recruitment, survival and the population growth rate of cascades frogs.",
    "citations": []
  },
  {
    "statement": "Eliminating fish using rotenone increased the number of amphibian species.",
    "citations": []
  },
  {
    "statement": "Eliminating fish using rotenone increased the abundance and recruitment of newt populations.",
    "citations": []
  },
  {
    "statement": "Fish exclusion using barriers increased the weight gain of axolotls.",
    "citations": []
  },
  {
    "statement": "Pond drying to eliminate fish increased the number of amphibian species.",
    "citations": []
  },
  {
    "statement": "Pond drying to eliminate fish increased the breeding success of frogs and newts.",
    "citations": []
  },
  {
    "statement": "Several harms and limitations of fish control for amphibian protection were documented.",
    "citations": []
  },
  {
    "statement": "Fish control had no significant effect on great crested newt populations.",
    "citations": []
  },
  {
    "statement": "After fish control efforts, fish remained or returned within a few years.",
    "citations": []
  },
  {
    "statement": "Fish control did not increase the breeding success of green toads.",
    "citations": []
  },
  {
    "statement": "In one case where fish control did not work, fish were soon reintroduced.",
    "citations": []
  },
  {
    "statement": "When the chemical rotenone was applied to control fish, many frogs died.",
    "citations": []
  },
  {
    "statement": "When the chemical rotenone was applied to control fish, a small number of newts showed symptoms of negative effects.",
    "citations": []
  },
  {
    "statement": "While fish control can benefit some amphibian populations, the methods used can also directly harm amphibians.",
    "citations": []
  },
  {
    "statement": "Fish control methods may not provide long-term solutions if fish reinvade the area.",
    "citations": []
  }
]

[
  {
    "statement": "Evidence from amphibian conservation efforts demonstrates significant volunteer engagement and participation across Europe and North America.",
    "citations": []
  },
  {
    "statement": "Citizen science projects have successfully engaged substantial numbers of volunteers.",
    "citations": []
  },
  {
    "statement": "Citizen science programs have involved between 100 and 10,506 volunteers active across 16 to 17 US states.",
    "citations": []
  },
  {
    "statement": "Volunteers in citizen science programs conducted 412 surveys at 121 to 7,872 sites.",
    "citations": []
  },
  {
    "statement": "Volunteers in citizen science programs swabbed nearly 6,000 amphibians.",
    "citations": []
  },
  {
    "statement": "Habitat management programs with volunteer participation have shown positive impacts on amphibian populations.",
    "citations": []
  },
  {
    "statement": "Before-and-after studies in Estonia and Taiwan showed increased natterjack toad and Taipei frog populations.",
    "citations": []
  },
  {
    "statement": "Between 8 and 41,000 volunteers engaged in habitat management programs.",
    "citations": []
  },
  {
    "statement": "Volunteers involved in habitat management restored up to 1,023 ponds.",
    "citations": []
  },
  {
    "statement": "Volunteers involved in habitat management restored over 11,500 square kilometers of habitat.",
    "citations": []
  },
  {
    "statement": "Public awareness campaigns have reached over 50,000 members of the public annually.",
    "citations": []
  },
  {
    "statement": "Public awareness campaigns have trained 1,016 people at 57 events over four years.",
    "citations": []
  },
  {
    "statement": "Awareness interventions in Mexico increased tourist knowledge of axolotls.",
    "citations": []
  },
  {
    "statement": "Amphibian road crossing patrols have been highly effective in moving large numbers of animals.",
    "citations": []
  },
  {
    "statement": "Road crossing patrol programs have relocated up to half a million amphibians during breeding migrations annually across Germany, the UK, and Italy.",
    "citations": []
  },
  {
    "statement": "Some programs relocated 7,532 toads before or after the breeding season.",
    "citations": []
  },
  {
    "statement": "The UK alone has had over 400 amphibian road crossing patrols.",
    "citations": []
  },
  {
    "statement": "Some amphibian road crossing patrols have been operating for up to 10 years.",
    "citations": []
  },
  {
    "statement": "A group of 71 patrols averaged 90 person-hours of volunteer work.",
    "citations": []
  }
]

[
  {
    "statement": "Based on global reviews and studies, amphibian translocations show moderate success rates.",
    "citations": []
  },
  {
    "statement": "One global review found that 65% of amphibian translocations resulted in established breeding populations or substantial recruitment to the adult population.",
    "citations": []
  },
  {
    "statement": "Another review found that success rates for amphibian translocations were higher when the translocations involved over 1,000 animals.",
    "citations": []
  },
  {
    "statement": "The success of amphibian translocations was not related to whether the animals were from wild or captive sources.",
    "citations": []
  },
  {
    "statement": "The success of amphibian translocations was not related to the life-stage of the animals, the continent, or the reason for translocation.",
    "citations": []
  },
  {
    "statement": "Studies on natterjack toads showed that translocated eggs, tadpoles, juveniles, or adults established breeding populations in 30-70% of cases.",
    "citations": []
  },
  {
    "statement": "Head-starting programs for amphibians have shown mixed success.",
    "citations": []
  },
  {
    "statement": "Six of ten studies on head-starting found that released head-started animals established breeding populations or increased populations.",
    "citations": []
  },
  {
    "statement": "Two of ten studies on head-starting found mixed results, and two studies found no establishment of breeding populations.",
    "citations": []
  },
  {
    "statement": "Releases of captive-bred green and golden bell frogs showed poor outcomes.",
    "citations": []
  },
  {
    "statement": "Studies found that captive-bred green and golden bell frogs released mainly as tadpoles did not establish breeding populations.",
    "citations": []
  },
  {
    "statement": "Stable breeding populations of green and golden bell frogs were only established following one out of four release programmes.",
    "citations": []
  },
  {
    "statement": "While some amphibian translocations achieve success, the establishment of new populations is challenging.",
    "citations": []
  },
  {
    "statement": "The establishment of new amphibian populations through the release of captive-bred individuals appears to be challenging.",
    "citations": []
  },
  {
    "statement": "Success rates for establishing new amphibian populations vary significantly between species and programs.",
    "citations": []
  }
]

[
  {
    "statement": "Increasing the water temperature of amphibian enclosures to 30-37°C for over 16 hours is an environmental management action that can help reduce chytridiomycosis.",
    "citations": []
  },
  {
    "statement": "In studies in Australia, Switzerland and the USA, increasing water temperature cured frogs and toads of chytridiomycosis.",
    "citations": []
  },
  {
    "statement": "Adding salt to ponds has shown effectiveness in reducing chytridiomycosis.",
    "citations": []
  },
  {
    "statement": "In one Australian study, a population of green and golden bell frogs remained free of chytridiomycosis for at least six months after salt was added to a pond containing the chytrid fungus.",
    "citations": []
  },
  {
    "statement": "Pond drying combined with treatment of resident amphibians can reduce chytrid infection levels.",
    "citations": []
  },
  {
    "statement": "One study found that pond drying combined with treatment of resident amphibians did not fully eradicate the disease.",
    "citations": []
  },
  {
    "statement": "A disease prevention protocol includes sterilizing equipment when moving between amphibian sites.",
    "citations": []
  },
  {
    "statement": "A disease prevention protocol includes using gloves when handling amphibians.",
    "citations": []
  },
  {
    "statement": "Evidence indicates that latex gloves can cause deaths of tadpoles in multiple species.",
    "citations": []
  },
  {
    "statement": "Vinyl and nitrile gloves have mixed safety results across different amphibian species tested.",
    "citations": []
  }
]

[
  {
    "statement": "Three studies in the USA found that understory removal using herbicide had no effect or some negative effects on amphibian abundance.",
    "citations": [
      "778"
    ]
  },
  {
    "statement": "One replicated, site comparison study in Canada found that following logging, American toad abundance was similar in stands with herbicide treatment compared to stands left to regenerate naturally.",
    "citations": [
      "778"
    ]
  },
  {
    "statement": "One replicated, site comparison study in Canada found that following logging, wood frog abundance was lower in stands with herbicide treatment compared to stands left to regenerate naturally.",
    "citations": [
      "778"
    ]
  },
  {
    "statement": "A randomized, replicated, controlled study in the USA found that the number of amphibian species was significantly higher in plots with mechanical understory reduction compared to plots without the reduction.",
    "citations": [
      "781"
    ]
  },
  {
    "statement": "A randomized, replicated, controlled study in the USA found that amphibian abundance was not significantly higher in plots with mechanical understory reduction compared to plots without the reduction.",
    "citations": [
      "781"
    ]
  }
]

[
  {
    "statement": "Multiple treatments are available for amphibians infected with chytridiomycosis.",
    "citations": []
  },
  {
    "statement": "Antifungal treatments are the most commonly studied approach for treating chytridiomycosis in amphibians.",
    "citations": []
  },
  {
    "statement": "Studies found that antifungal treatment cured or increased the survival of amphibians with chytridiomycosis.",
    "citations": []
  },
  {
    "statement": "Studies testing treatment with itraconazole found the antifungal was effective at curing amphibians.",
    "citations": []
  },
  {
    "statement": "One study found that treatment with itraconazole reduced infection levels in amphibians.",
    "citations": []
  },
  {
    "statement": "One study found that treatment with itraconazole had mixed effects.",
    "citations": []
  },
  {
    "statement": "Temperature treatment is another effective approach for chytridiomycosis.",
    "citations": []
  },
  {
    "statement": "Increasing temperature to 30-37°C for over 16 hours was found to cure frogs and toads of chytridiomycosis.",
    "citations": []
  },
  {
    "statement": "Wild treatment approaches for chytridiomycosis have shown more limited success.",
    "citations": []
  },
  {
    "statement": "Treating wild midwife toads with fungicide along with pond drying reduced infection levels but did not eradicate chytridiomycosis.",
    "citations": []
  },
  {
    "statement": "Adding salt to ponds was found to keep a population of green and golden bell frogs free of chytridiomycosis for at least six months.",
    "citations": []
  },
  {
    "statement": "Vaccination with formalin-killed chytrid fungus did not significantly reduce infection rates or mortality in mountain yellow-legged frogs.",
    "citations": []
  },
  {
    "statement": "Some treatments for chytridiomycosis in amphibians carry risks.",
    "citations": []
  },
  {
    "statement": "Six studies found that specific fungicides caused death or other negative side effects in amphibians.",
    "citations": []
  }
]

[
  {
    "statement": "For amphibian conservation in North America, wetland creation has demonstrated effectiveness.",
    "citations": [
      "869",
      "880",
      "879"
    ]
  },
  {
    "statement": "For amphibian conservation in North America, wetland restoration has demonstrated effectiveness.",
    "citations": [
      "879"
    ]
  },
  {
    "statement": "The outcomes for amphibian conservation from wetland creation and restoration vary by context.",
    "citations": [
      "880",
      "879"
    ]
  },
  {
    "statement": "Studies show that created wetlands were colonized by amphibians.",
    "citations": [
      "869"
    ]
  },
  {
    "statement": "Studies show that 64-100% of created wetland ponds were used by amphibians.",
    "citations": [
      "869"
    ]
  },
  {
    "statement": "Studies show that 64-68% of created wetland ponds supported amphibian reproduction.",
    "citations": [
      "869"
    ]
  },
  {
    "statement": "Site comparison studies in the USA found that in some cases, created wetlands had similar numbers of amphibian species and abundance as natural wetlands.",
    "citations": [
      "880"
    ]
  },
  {
    "statement": "Other studies in the USA found that created wetlands had fewer amphibian species or lower amphibian abundance than natural wetlands.",
    "citations": [
      "880"
    ]
  },
  {
    "statement": "Eight of ten site comparison studies in Canada and the USA found that amphibian abundance, species numbers, and species composition in restored wetlands were similar to natural wetlands.",
    "citations": [
      "879"
    ]
  },
  {
    "statement": "A global review found that in 89% of cases, restored and created wetlands had similar or higher amphibian abundance or species numbers compared to natural wetlands.",
    "citations": [
      "879"
    ]
  },
  {
    "statement": "Wetland creation and wetland restoration can maintain or increase amphibian populations.",
    "citations": [
      "880",
      "879"
    ]
  },
  {
    "statement": "The success of wetland creation and restoration is influenced by factors such as wetland design, vegetation, water levels, and surrounding habitat.",
    "citations": [
      "880",
      "879"
    ]
  },
  {
    "statement": "The success of wetland creation and restoration is influenced by the proximity to source amphibian populations.",
    "citations": [
      "880",
      "879"
    ]
  }
]

[
  {
    "statement": "In US forests, the effects of prescribed fire on amphibian populations are variable.",
    "citations": []
  },
  {
    "statement": "Eight of 14 studies found no effect of prescribed forest fires on amphibian abundance or the number of amphibian species.",
    "citations": []
  },
  {
    "statement": "Four studies found the effects of prescribed fire on amphibians were mixed, depending on the species, year, or season of the burn.",
    "citations": []
  },
  {
    "statement": "Three studies showed that prescribed fires increased amphibian abundance or the number of amphibian species.",
    "citations": []
  },
  {
    "statement": "One study found that amphibian abundance decreased with prescribed fires.",
    "citations": []
  },
  {
    "statement": "Two studies found that the number of amphibian species and their abundance either increased or decreased with the time since a prescribed forest fire.",
    "citations": []
  },
  {
    "statement": "One study found that the hatching success of spotted salamanders increased following a prescribed forest fire.",
    "citations": []
  },
  {
    "statement": "In grassland habitats, prescribed fire shows more consistently negative impacts on amphibians.",
    "citations": []
  },
  {
    "statement": "Two studies found that annual prescribed fires decreased the number of amphibian species and their abundance.",
    "citations": []
  },
  {
    "statement": "Two studies found that annual prescribed fires increased rates of amphibian species loss when combined with changes in grazing regimes.",
    "citations": []
  },
  {
    "statement": "One replicated study found that spring burns decreased salamander abundance.",
    "citations": []
  },
  {
    "statement": "One replicated study found that autumn and winter burns showed no effect on salamander abundance.",
    "citations": []
  }
]

[
  {
    "statement": "Removing invasive predators can benefit native amphibians.",
    "citations": []
  },
  {
    "statement": "Removing fish by catching them significantly increased the abundance of salamanders or frogs.",
    "citations": []
  },
  {
    "statement": "Removing fish by catching them increased the recruitment, survival and population growth rate of cascades frogs.",
    "citations": []
  },
  {
    "statement": "Eliminating fish using the chemical rotenone increased the numbers of amphibian species.",
    "citations": []
  },
  {
    "statement": "Eliminating fish using the chemical rotenone increased the abundance and recruitment of newt populations.",
    "citations": []
  },
  {
    "statement": "Draining ponds to eliminate fish increased the numbers of amphibian species.",
    "citations": []
  },
  {
    "statement": "Removing American bullfrogs significantly increased a population of California red-legged frogs.",
    "citations": []
  },
  {
    "statement": "Eradicating bullfrogs increased the range of leopard frogs.",
    "citations": []
  },
  {
    "statement": "Evidence for mammal predator control shows mixed results.",
    "citations": []
  },
  {
    "statement": "Controlling rats had no significant effect on the numbers of Hochstetter's frog.",
    "citations": []
  },
  {
    "statement": "The survival of Maud Island frogs was significantly higher in a predator-proof enclosure than in the wild.",
    "citations": []
  },
  {
    "statement": "Some predator removal methods have reported negative effects.",
    "citations": []
  },
  {
    "statement": "When the chemical rotenone was applied for predator removal, many frogs died.",
    "citations": []
  },
  {
    "statement": "When the chemical rotenone was applied for predator removal, some newts showed symptoms of negative effects.",
    "citations": []
  }
]

[
  {
    "statement": "Mallorcan midwife toad reintroduction programs in Mallorca showed higher success rates compared to green and golden bell frog programs in Australia.",
    "citations": []
  },
  {
    "statement": "Captive-bred Mallorcan midwife toads released as tadpoles, toadlets, or adults established breeding populations at 38% of sites.",
    "citations": []
  },
  {
    "statement": "Captive-bred Mallorcan midwife toads released as tadpoles, toadlets, or adults established breeding populations at 80% of sites.",
    "citations": []
  },
  {
    "statement": "Captive-bred Mallorcan midwife toads released as tadpoles, toadlets, or adults established breeding populations at 100% of sites.",
    "citations": []
  },
  {
    "statement": "Green and golden bell frog reintroductions in Australia showed limited success.",
    "citations": []
  },
  {
    "statement": "Captive-bred green and golden bell frogs released mainly as tadpoles did not establish breeding populations.",
    "citations": []
  },
  {
    "statement": "Stable breeding populations of green and golden bell frogs were established following only one of four release programmes.",
    "citations": []
  },
  {
    "statement": "A small proportion of captive-bred green and golden bell frogs released as tadpoles survived at least 13 months after release.",
    "citations": []
  },
  {
    "statement": "The Mallorcan midwife toad captive breeding programs achieved 85% survival to metamorphosis.",
    "citations": []
  },
  {
    "statement": "Mallorcan midwife toads bred in captivity for nine or more generations showed slower tadpole development.",
    "citations": []
  },
  {
    "statement": "Mallorcan midwife toads bred in captivity for nine or more generations showed a reduction in one predator defence trait.",
    "citations": []
  },
  {
    "statement": "Mallorcan midwife toads bred in captivity for nine or more generations showed decreased genetic diversity.",
    "citations": []
  }
]

[
  {
    "statement": "In Australian captive breeding programs, both hormone treatments and artificial fertilization have shown mixed results with specific challenges for frogs.",
    "citations": []
  },
  {
    "statement": "Hormone treatments to induce sperm and egg release have demonstrated success in stimulating reproduction in frogs.",
    "citations": [
      "883",
      "3767"
    ]
  },
  {
    "statement": "Studies show male hormone treatment can stimulate or increase sperm production and result in successful breeding in captivity.",
    "citations": [
      "883",
      "3767"
    ]
  },
  {
    "statement": "Hormone treatments show variable results for female frogs.",
    "citations": [
      "883"
    ]
  },
  {
    "statement": "Depending on the combination, amount, or number of doses of hormones, 30-71% of female frogs produce viable eggs.",
    "citations": [
      "883"
    ]
  },
  {
    "statement": "Some studies found that hormone treatment did not stimulate egg production in certain cases.",
    "citations": []
  },
  {
    "statement": "Artificial fertilization has also shown limited success in frogs.",
    "citations": [
      "834"
    ]
  },
  {
    "statement": "One Australian study found that 55% of eggs were fertilized artificially but soon died.",
    "citations": [
      "834"
    ]
  },
  {
    "statement": "The success of artificial fertilization depends on the type and number of hormone doses used to stimulate egg production beforehand.",
    "citations": [
      "834"
    ]
  },
  {
    "statement": "Both artificial fertilization and hormone treatments require careful optimization of hormone protocols.",
    "citations": []
  },
  {
    "statement": "Neither hormone treatments nor artificial fertilization guarantees consistent breeding success across different frog species in Australian captive programs.",
    "citations": []
  }
]

[
  {
    "statement": "Releasing captive-bred individuals is an alternative species augmentation technique to establish or increase amphibian populations.",
    "citations": []
  },
  {
    "statement": "Head-starting amphibians for release is an alternative species augmentation technique to establish or increase amphibian populations.",
    "citations": []
  },
  {
    "statement": "Using hormone treatments to enhance captive breeding success is an alternative species augmentation technique to establish or increase amphibian populations.",
    "citations": []
  },
  {
    "statement": "One review found that 41% of release programmes for captive-bred or head-started amphibians showed evidence of breeding in the wild for multiple generations.",
    "citations": []
  },
  {
    "statement": "A review found 29% of release programmes for captive-bred or head-started amphibians showed some evidence of breeding.",
    "citations": []
  },
  {
    "statement": "Head-starting involves rearing amphibians from eggs to later life stages such as tadpoles, metamorphs or juveniles before release.",
    "citations": []
  },
  {
    "statement": "Six of ten studies found that released head-started individuals established breeding populations or increased existing populations.",
    "citations": []
  },
  {
    "statement": "Nine of ten studies found that head-started amphibians released at various life stages successfully metamorphosed.",
    "citations": []
  },
  {
    "statement": "Nine of ten studies found that head-started amphibians released at various life stages survived the amphibians' first season or year.",
    "citations": []
  },
  {
    "statement": "Nine of ten studies found that head-started amphibians released at various life stages bred successfully.",
    "citations": []
  },
  {
    "statement": "Captive breeding programs can be enhanced using hormone treatments to induce sperm and egg release.",
    "citations": []
  },
  {
    "statement": "Nine of ten studies showed successful stimulation of male sperm production through hormone treatments.",
    "citations": []
  },
  {
    "statement": "Studies on hormone treatments for female egg production have shown mixed but generally positive results.",
    "citations": []
  },
  {
    "statement": "Releasing captive-bred individuals, head-starting amphibians, and using hormone treatments are techniques that allow for population establishment or augmentation without the need for creating new pond habitats.",
    "citations": []
  }
]

[
  {
    "statement": "Studies comparing physical interventions for protecting migrating amphibians show varying effectiveness.",
    "citations": []
  },
  {
    "statement": "Barrier fencing with culverts decreased amphibian road deaths in seven of eight studies from Germany, Canada, and the USA.",
    "citations": []
  },
  {
    "statement": "The effectiveness of barrier fencing was dependent on the fence length and material.",
    "citations": []
  },
  {
    "statement": "Barriers at least 0.6 meters high were required to prevent frogs from climbing over the barriers.",
    "citations": []
  },
  {
    "statement": "Treefrogs and 10% of common toads still climbed over barrier fencing during breeding migrations.",
    "citations": []
